/** Explicit phenotype coding, complete-case ledger and original null-model contract. */
final class SaigeNullInputs {
    private SaigeNullInputs() { }
    record Covariate(String column,List<String> levels) {Covariate{levels=List.copyOf(levels);}}
    record Spec(SaigeGrmInputs.Spec genotypes,Path phenotype,String delimiter,String id,String response,
                String trait,String control,String caseCode,List<Covariate> covariates,Set<String> missing,
                boolean excludeMissing,boolean irnt,boolean loco,boolean sparse,boolean sparseRatio,
                boolean covariateOffset,Path grmBundle,Map<?,?> parameters,long modelCells) {
        Spec{covariates=List.copyOf(covariates);missing=Set.copyOf(missing);}
    }
    record Prepared(Spec spec,SaigeGrmInputs.Prepared genotypes,List<String> sampleIds,double[] outcomes,
                    double[] design,int columns,Path phenotype,Map<Path,String> immutable,Map<String,Object> admission) {
        Prepared{sampleIds=List.copyOf(sampleIds);outcomes=outcomes.clone();design=design.clone();immutable=Map.copyOf(immutable);admission=Collections.unmodifiableMap(new LinkedHashMap<>(admission));}
        @Override public double[] outcomes(){return outcomes.clone();}
        @Override public double[] design(){return design.clone();}
        void verify()throws IOException {genotypes.verify();for(var entry:immutable.entrySet())if(!FollowupSupport.hash(entry.getKey()).equals(entry.getValue()))throw new IOException("Null-model source or snapshot changed: "+entry.getKey());}
    }
    static Spec read(Path file)throws Exception {
        file=file.toAbsolutePath().normalize();if(!Files.isRegularFile(file)||Files.size(file)>2L*1048576)throw new IOException("Require a UTF8 null-model recipe at most 2MiB");byte[] raw=Files.readAllBytes(file);Map<?,?> root=map(SimpleJson.parse(StandardCharsets.UTF_8.newDecoder().decode(ByteBuffer.wrap(raw)).toString()));
        keys(root,Set.of("version","operation","genotypes","genotype_coding","assembly","phenotypes","model","parameters","resources","sparse_grm_bundle"));whole(root,"version",1,1);if(!text(root,"operation").equals("fit-null"))throw new IOException("Require operation=fit-null");if(!text(root,"genotype_coding").equals("diploid-autosomal-plink-bed"))throw new IOException("Null-model profile requires declared diploid-autosomal-plink-bed coding");
        String assembly=text(root,"assembly");token(assembly,"assembly",false);Path prefix=resolve(file,text(root,"genotypes"));Map<?,?> r=map(root.get("resources"));keys(r,Set.of("threads","memory_chunk_gib","max_samples","max_variants","max_input_bytes","max_genotype_cells","max_matrix_entries","max_model_cells"));
        Limits limits=new Limits((int)optional(r,"max_samples",1_000_000,1,1_000_000),(int)optional(r,"max_variants",1_000_000,1,5_000_000),optional(r,"max_input_bytes",4L*1073741824,1,64L*1024*1073741824),optional(r,"max_genotype_cells",1_000_000_000,1,10_000_000_000_000L),optional(r,"max_matrix_entries",20_000_000,1,1_000_000_000),(int)whole(r,"threads",1,64),number(r,"memory_chunk_gib",.001,256));long cells=optional(r,"max_model_cells",2_000_000,1,20_000_000);
        Map<?,?> p=map(root.get("parameters"));keys(p,Set.of("min_maf","max_missing","seed","diagonal","variance_ratio","fit_tolerance","max_iterations","pcg_tolerance","max_pcg_iterations","trace_cv","trace_runs","spa_cutoff","tau_initial","relatedness_cutoff"));double maf=number(p,"min_maf",0,.5),missing=number(p,"max_missing",0,1),cutoff=number(p,"relatedness_cutoff",0,2);whole(p,"seed",1,1);if(!text(p,"diagonal").equals("observed"))throw new IOException("Only explicitly observed GRM diagonals are exposed");number(p,"fit_tolerance",1e-12,1);whole(p,"max_iterations",1,10000);number(p,"pcg_tolerance",1e-15,1);whole(p,"max_pcg_iterations",1,100000);number(p,"trace_cv",1e-9,1);whole(p,"trace_runs",1,100000);number(p,"spa_cutoff",0,100);List<Double> tau=numbers(p.get("tau_initial"),2,2,0,1e10);if(tau.size()!=2)throw new IOException("Require two explicit tau_initial values");
        Map<?,?> vr=map(p.get("variance_ratio"));String kind=text(vr,"kind");if(!Set.of("single","categorical").contains(kind))throw new IOException("Variance-ratio kind must be single or categorical");
        if(kind.equals("single")){keys(vr,Set.of("kind","minimum_mac","num_markers","coefficient_variation"));whole(vr,"minimum_mac",20,20);}
        else {keys(vr,Set.of("kind","lower_exclusive","upper_inclusive","num_markers","coefficient_variation"));List<Double> lower=numbers(vr.get("lower_exclusive"),2,32,0,1e10),upper=numbers(vr.get("upper_inclusive"),1,31,0,1e10);if(upper.size()!=lower.size()-1)throw new IOException("Categorical variance-ratio bin vectors have inconsistent sizes");for(int i=0;i<upper.size();i++)if(upper.get(i)<=lower.get(i)||Double.compare(upper.get(i),lower.get(i+1))!=0)throw new IOException("Variance-ratio MAC bins must be contiguous, increasing lower-exclusive/upper-inclusive intervals");}
        whole(vr,"num_markers",1,100000);number(vr,"coefficient_variation",1e-9,1);
        Map<?,?> m=map(root.get("model"));keys(m,Set.of("trait_type","inverse_normalize","loco","relationship","sparse_variance_ratio","covariate_offset"));String trait=text(m,"trait_type"),relationship=text(m,"relationship");if(!Set.of("binary","quantitative").contains(trait)||!Set.of("sparse","full").contains(relationship))throw new IOException("Declare binary/quantitative trait and sparse/full relationship");boolean irnt=bool(m,"inverse_normalize"),loco=bool(m,"loco"),sparse=relationship.equals("sparse"),sparseRatio=bool(m,"sparse_variance_ratio"),offset=bool(m,"covariate_offset");if(irnt&&trait.equals("binary"))throw new IOException("Binary outcomes cannot request quantitative IRNT");if(loco&&(sparse||kind.equals("categorical")))throw new IOException("Original LOCO requires full GRM and noncategorical variance ratio");Path grm=null;if(sparse||sparseRatio){grm=resolve(file,text(root,"sparse_grm_bundle"));}else if(root.containsKey("sparse_grm_bundle"))throw new IOException("Unconsumed sparse_grm_bundle is not allowed");
        Map<?,?> ph=map(root.get("phenotypes"));keys(ph,trait.equals("binary")?Set.of("file","delimiter","id","response","control","case","covariates","missing","missing_policy"):Set.of("file","delimiter","id","response","covariates","missing","missing_policy"));String delimiter=text(ph,"delimiter");if(!Set.of("tab","whitespace").contains(delimiter))throw new IOException("Declare tab or whitespace phenotype delimiter");String id=text(ph,"id"),response=text(ph,"response"),policy=text(ph,"missing_policy");token(id,"ID column",true);token(response,"response column",true);if(id.equals(response)||!Set.of("error","exclude-with-ledger").contains(policy))throw new IOException("Distinct ID/response and explicit missing_policy are required");String control=trait.equals("binary")?text(ph,"control"):"",caseCode=trait.equals("binary")?text(ph,"case"):"";if(trait.equals("binary")&&control.equals(caseCode))throw new IOException("Case and control labels must differ");
        List<String> missingTokens=strings(ph.get("missing"),0,32);var missingSet=new HashSet<>(missingTokens);if(missingSet.contains(control)&&trait.equals("binary")||missingSet.contains(caseCode)&&trait.equals("binary"))throw new IOException("Case/control label overlaps a missing token");Object covs=ph.get("covariates");if(!(covs instanceof List<?> list)||list.size()>64)throw new IOException("Require an explicit bounded covariates array, including [] for none");var covariates=new ArrayList<Covariate>();var columns=new HashSet<>(Set.of(id,response));int designColumns=1;
        for(Object value:list){Map<?,?> cov=map(value);String type=text(cov,"kind"),name=text(cov,"column");token(name,"covariate column",true);if(!columns.add(name))throw new IOException("Duplicate/overlapping phenotype column");List<String> levels;if(type.equals("numeric")){keys(cov,Set.of("column","kind"));levels=List.of();designColumns++;}else if(type.equals("categorical")){keys(cov,Set.of("column","kind","levels"));levels=strings(cov.get("levels"),2,32);for(String level:levels)if(level.isEmpty()||missingSet.contains(level))throw new IOException("Category level is empty or overlaps a missing token");designColumns+=levels.size()-1;}else throw new IOException("Covariate kind must be numeric or categorical");covariates.add(new Covariate(name,levels));}
        if(designColumns>128)throw new IOException("Expanded null design exceeds 128 columns");if(offset&&(designColumns==1||trait.equals("binary")&&designColumns==2))throw new IOException("Original SAIGE overrides covariate_offset for this design;explicitly request false to avoid an inferred model change");
        var genotypeSpec=new SaigeGrmInputs.Spec(file,java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(raw)),prefix,assembly,1,cutoff,maf,missing,limits,root);
        return new Spec(genotypeSpec,resolve(file,text(ph,"file")),delimiter,id,response,trait,control,caseCode,covariates,missingSet,policy.equals("exclude-with-ledger"),irnt,loco,sparse,sparseRatio,offset,grm,p,cells);
    }
    static Prepared prepare(Spec spec,Path work)throws Exception {
        SaigeGrmInputs.Prepared genotypes=SaigeGrmInputs.prepare(spec.genotypes,work);Path source=spec.phenotype;if(!Files.isRegularFile(source)||Files.size(source)>spec.genotypes.limits().bytes())throw new IOException("Phenotype input is absent or exceeds max_input_bytes");String hash=FollowupSupport.hash(source);Path snapshot=work.resolve("inputs/supplied-phenotypes.txt");Files.copy(source,snapshot);if(!hash.equals(FollowupSupport.hash(snapshot)))throw new IOException("Phenotypes changed during snapshot");var immutable=new LinkedHashMap<Path,String>();immutable.put(source,hash);immutable.put(snapshot,hash);
        var rows=new LinkedHashMap<String,String[]>();List<String> header;
        try(var reader=Files.newBufferedReader(snapshot,StandardCharsets.UTF_8)) {
            String line=SaigeGrmInputs.line(reader,65536);if(line==null)throw new IOException("Empty phenotype table");header=List.of(fields(line,spec.delimiter));if(new HashSet<>(header).size()!=header.size())throw new IOException("Duplicate phenotype header");
            var selected=new ArrayList<String>(List.of(spec.id,spec.response));for(Covariate cov:spec.covariates)selected.add(cov.column);if(!header.containsAll(selected))throw new IOException("Required phenotype columns absent: "+selected);int idIndex=header.indexOf(spec.id);
            while((line=SaigeGrmInputs.line(reader,65536))!=null){if(line.isBlank())throw new IOException("Blank phenotype row");String[] row=fields(line,spec.delimiter);if(row.length!=header.size()||rows.size()>=spec.genotypes.limits().samples())throw new IOException("Phenotype field count or row bound exceeded");String id=row[idIndex];token(id,"phenotype IID",true);if(rows.put(id,row)!=null)throw new IOException("Duplicate phenotype IID: "+id);}
        }
        int p=1;var aliases=new ArrayList<String>();for(Covariate cov:spec.covariates){int width=cov.levels.isEmpty()?1:cov.levels.size()-1;for(int j=0;j<width;j++)aliases.add("c"+aliases.size());p+=width;}
        var ids=new ArrayList<String>();var outcomes=new ArrayList<Double>();var designRows=new ArrayList<double[]>();var ledger=new ArrayList<Map<String,Object>>();int responseIndex=header.indexOf(spec.response);var sourceIds=new HashSet<>(genotypes.sampleIds());
        for(String id:rows.keySet())if(!sourceIds.contains(id))ledger.add(Map.of("sample",id,"status","excluded-no-array-genotype"));
        for(String id:genotypes.sampleIds()) {
            String[] row=rows.get(id);String reason=null;if(row==null)reason="absent-phenotype-row";else {var required=new ArrayList<String>(List.of(spec.response));for(Covariate cov:spec.covariates)required.add(cov.column);for(String name:required){String value=row[header.indexOf(name)];if(value.isEmpty()||spec.missing.contains(value)){reason="missing:"+name;break;}}}
            if(reason!=null){if(!spec.excludeMissing)throw new IOException("Incomplete null-model sample "+id+": "+reason);ledger.add(Map.of("sample",id,"status","excluded-"+reason));continue;}
            double y;if(spec.trait.equals("binary")){String value=row[responseIndex];if(!value.equals(spec.control)&&!value.equals(spec.caseCode))throw new IOException("Undeclared binary response label for "+id);y=value.equals(spec.caseCode)?1:0;}else y=finite(row[responseIndex],"quantitative response");
            double[] x=new double[p];x[0]=1;int at=1;for(Covariate cov:spec.covariates){String value=row[header.indexOf(cov.column)];if(cov.levels.isEmpty())x[at++]=finite(value,"numeric covariate");else {int level=cov.levels.indexOf(value);if(level<0)throw new IOException("Undeclared categorical level in "+cov.column+" for "+id);for(int j=1;j<cov.levels.size();j++)x[at++]=level==j?1:0;}}
            ids.add(id);outcomes.add(y);designRows.add(x);ledger.add(Map.of("sample",id,"status","included"));
        }
        int n=ids.size();long cells=Math.multiplyExact((long)n,p+5L+(spec.loco?44:0));if(n<=p||n<4||cells>spec.modelCells)throw new IOException("Null model requires at least four complete samples, positive residual degrees of freedom and max_model_cells admission");double[] y=outcomes.stream().mapToDouble(Double::doubleValue).toArray(),x=new double[Math.multiplyExact(n,p)];int cases=0;for(int i=0;i<n;i++){System.arraycopy(designRows.get(i),0,x,i*p,p);if(y[i]==1)cases++;}
        if(spec.trait.equals("binary")&&(cases<2||n-cases<2))throw new IOException("Binary null profile requires at least two declared cases and controls");if(spec.trait.equals("quantitative")&&Arrays.stream(y).min().orElseThrow()==Arrays.stream(y).max().orElseThrow())throw new IOException("Quantitative response is constant");
        try(BackendContext context=BackendContext.select(BackendPolicy.CPU)){if(context.backend().dgeqp3(x.clone(),n,p).rank()!=p)throw new IOException("Native complete-case null design is rank deficient");}
        if(spec.trait.equals("binary"))for(int j=1;j<p;j++){var levels=new HashMap<Double,int[]>();for(int i=0;i<n;i++)levels.computeIfAbsent(x[i*p+j],v->new int[2])[(int)y[i]]++;if(levels.size()==2)for(int[] count:levels.values())if(count[0]==0||count[1]==0)throw new IOException("A binary/categorical design contrast perfectly separates the declared response;review model coding before fitting");}
        Path staged=work.resolve("inputs/phenotypes.tsv");try(var writer=Files.newBufferedWriter(staged,StandardCharsets.UTF_8)){writer.write("IID\ty"+(aliases.isEmpty()?"":"\t"+String.join("\t",aliases))+"\n");for(int i=0;i<n;i++){writer.write(ids.get(i)+"\t"+y[i]);for(int j=1;j<p;j++)writer.write("\t"+x[i*p+j]);writer.write("\n");}}immutable.put(staged,FollowupSupport.hash(staged));
        try(var writer=Files.newBufferedWriter(work.resolve("cohort-ledger.tsv"),StandardCharsets.UTF_8)){writer.write("sample\tstatus\n");for(var row:ledger)writer.write(row.get("sample")+"\t"+row.get("status")+"\n");}
        if(spec.irnt)y=irnt(y);Map<String,Object> admission=new LinkedHashMap<>();admission.put("source_array_samples",genotypes.sampleIds().size());admission.put("phenotype_rows",rows.size());admission.put("complete_model_samples",n);admission.put("excluded_array_samples",genotypes.sampleIds().size()-n);admission.put("phenotype_rows_outside_array",rows.keySet().stream().filter(id->!sourceIds.contains(id)).count());admission.put("design_columns",p);admission.put("column_coding","intercept plus native numeric/dummy columns;declared first categorical level is baseline;safe aliases prevent formula interpretation");admission.put("trait_type",spec.trait);admission.put("inverse_normalize",spec.irnt);admission.put("cases",spec.trait.equals("binary")?cases:null);admission.put("controls",spec.trait.equals("binary")?n-cases:null);admission.put("model_export_cells_bound",cells);
        if(spec.grmBundle!=null)stageGrm(spec,ids,work,immutable,admission);
        if(spec.loco){var chromosomes=new HashSet<String>();try(var reader=Files.newBufferedReader(Path.of(genotypes.prefix()+".bim"),StandardCharsets.UTF_8)){for(String line;(line=SaigeGrmInputs.line(reader,16384))!=null;)if(!line.isBlank())chromosomes.add(line.strip().split("[ \\t]+")[0]);}for(int i=1;i<=22;i++)if(!chromosomes.contains(String.valueOf(i)))throw new IOException("Full LOCO profile requires explicit source markers on every autosome 1..22");}
        var prepared=new Prepared(spec,genotypes,ids,y,x,p,staged,immutable,admission);prepared.verify();return prepared;
    }
    private static void stageGrm(Spec spec,List<String> modelIds,Path work,Map<Path,String> immutable,Map<String,Object> admission)throws Exception {
        Path bundle=spec.grmBundle;long bytes=0;for(String name:List.of("grm.mtx","sample-ids.txt")){Path path=bundle.resolve(name);if(!Files.isRegularFile(path))throw new IOException("Missing sparse-GRM bundle input: "+name);bytes=Math.addExact(bytes,Files.size(path));}if(bytes>spec.genotypes.limits().bytes())throw new IOException("Sparse-GRM matrix/ID input exceeds max_input_bytes");if(Files.getFileStore(work).getUsableSpace()<bytes+64L*1048576)throw new IOException("Insufficient scratch storage for sparse-GRM snapshots");
        for(String name:List.of("analysis-status.json","results.json","native-audit.json","supplied-recipe.json")){Path path=bundle.resolve(name);if(!Files.isRegularFile(path)||Files.size(path)>2L*1048576)throw new IOException("Missing/oversized sparse-GRM metadata: "+name);immutable.put(path,FollowupSupport.hash(path));}Map<?,?> status=json(bundle.resolve("analysis-status.json"),1048576),results=json(bundle.resolve("results.json"),1048576),audit=json(bundle.resolve("native-audit.json"),2*1048576);
        if(!"completed-with-review-warnings".equals(status.get("status"))||!"sparse-grm".equals(results.get("operation"))||!Objects.equals(audit.get("assembly_declaration"),spec.genotypes.assembly()))throw new IOException("Sparse-GRM bundle must be a completed typed sparse-grm output with matching assembly declaration");
        if(!Objects.equals(results.get("native_audit_sha256"),FollowupSupport.hash(bundle.resolve("native-audit.json"))))throw new IOException("Sparse-GRM native audit changed");
        Map<?,?> oldRecipe=json(bundle.resolve("supplied-recipe.json"),2*1048576);double oldCutoff=number(map(oldRecipe.get("parameters")),"relatedness_cutoff",0,2);if(spec.genotypes.cutoff()<oldCutoff)throw new IOException("Requested null-model cutoff is below the sparse-GRM generation cutoff;lost pairs cannot be reconstructed");
        for(String name:List.of("grm.mtx","sample-ids.txt")){Path source=bundle.resolve(name);String digest=FollowupSupport.hash(source);String field=name.equals("grm.mtx")?"grm_sha256":"sample_ids_sha256";if(!digest.equals(results.get(field))||!digest.equals(audit.get(field)))throw new IOException("Sparse-GRM bundle member changed: "+name);Path staged=work.resolve("inputs/"+name);Files.copy(source,staged);if(!digest.equals(FollowupSupport.hash(staged)))throw new IOException("Sparse-GRM changed during snapshot");immutable.put(source,digest);immutable.put(staged,digest);}
        var ids=new ArrayList<String>();try(var reader=Files.newBufferedReader(work.resolve("inputs/sample-ids.txt"),StandardCharsets.UTF_8)){for(String line;(line=SaigeGrmInputs.line(reader,16384))!=null;){token(line,"sparse-GRM IID",true);if(ids.size()>=spec.genotypes.limits().samples())throw new IOException("Sparse-GRM sample bound exceeded");ids.add(line);}}if(new HashSet<>(ids).size()!=ids.size()||!new HashSet<>(ids).containsAll(modelIds))throw new IOException("Sparse-GRM IIDs must be unique and include every complete-case model IID");SaigeGrmInputs.auditMatrix(work.resolve("inputs/grm.mtx"),ids.size(),oldCutoff,spec.genotypes.limits().matrixEntries());admission.put("sparse_grm_sample_universe",ids.size());admission.put("sparse_grm_pair_coverage","candidate-screened;not-certified-complete-above-cutoff");
    }
    static List<String> command(Prepared prepared,Path work)throws Exception {
        Spec s=prepared.spec;Map<?,?> p=s.parameters,vr=map(p.get("variance_ratio"));boolean categorical=text(vr,"kind").equals("categorical");var command=new ArrayList<String>(List.of("--plinkFile="+prepared.genotypes.prefix(),"--phenoFile="+prepared.phenotype,"--phenoCol=y","--sampleIDColinphenoFile=IID","--traitType="+s.trait,"--outputPrefix="+work.resolve("original-null"),"--nThreads="+s.genotypes.limits().threads(),"--memoryChunk="+s.genotypes.limits().memoryGiB(),"--minMAFforGRM="+s.genotypes.minMaf(),"--maxMissingRateforGRM="+s.genotypes.maxMissing(),"--relatednessCutoff="+s.genotypes.cutoff(),"--invNormalize="+rbool(s.irnt),"--LOCO="+rbool(s.loco),"--useSparseGRMtoFitNULL="+rbool(s.sparse),"--useSparseGRMforVarRatio="+rbool(s.sparseRatio),"--isCovariateOffset="+rbool(s.covariateOffset),"--isCovariateTransform=TRUE","--minCovariateCount=-1","--isDiagofKinSetAsOne=FALSE","--skipModelFitting=FALSE","--skipVarianceRatioEstimation=FALSE","--IsOverwriteVarianceRatioFile=TRUE","--isCateVarianceRatio="+rbool(categorical),"--cateVarRatioMinMACVecExclude="+(categorical?join((List<?>)vr.get("lower_exclusive")):"10,20.5"),"--cateVarRatioMaxMACVecInclude="+(categorical?join((List<?>)vr.get("upper_inclusive")):"20.5"),"--numRandomMarkerforVarianceRatio="+whole(vr,"num_markers",1,100000),"--ratioCVcutoff="+vr.get("coefficient_variation"),"--tauInit="+join((List<?>)p.get("tau_initial"))));
        for(String[] pair:List.of(new String[]{"tol","fit_tolerance"},new String[]{"maxiter","max_iterations"},new String[]{"tolPCG","pcg_tolerance"},new String[]{"maxiterPCG","max_pcg_iterations"},new String[]{"traceCVcutoff","trace_cv"},new String[]{"nrun","trace_runs"},new String[]{"SPAcutoff","spa_cutoff"}))command.add("--"+pair[0]+"="+p.get(pair[1]));
        if(prepared.columns>1){var aliases=new ArrayList<String>();for(int j=0;j<prepared.columns-1;j++)aliases.add("c"+j);command.add("--covarColList="+String.join(",",aliases));}
        if(s.grmBundle!=null){command.add("--sparseGRMFile="+work.resolve("inputs/grm.mtx"));command.add("--sparseGRMSampleIDFile="+work.resolve("inputs/sample-ids.txt"));}return List.copyOf(command);
    }
    static double[] irnt(double[] values){Integer[] order=new Integer[values.length];for(int i=0;i<order.length;i++)order[i]=i;Arrays.sort(order,Comparator.comparingDouble(i->values[i]));double[] result=new double[values.length];int start=0;while(start<order.length){int end=start+1;while(end<order.length&&values[order[end]]==values[order[start]])end++;double probability=((start+1+end)/2.0-.5)/order.length;double score=Normal.quantile(probability,0,1,true,false);for(int i=start;i<end;i++)result[order[i]]=score;start=end;}return result;}
    static Map<?,?> json(Path path,int maximum)throws Exception {if(!Files.isRegularFile(path)||Files.size(path)>maximum)throw new IOException("Missing/oversized SAIGE JSON member: "+path);return map(SimpleJson.parse(StandardCharsets.UTF_8.newDecoder().decode(ByteBuffer.wrap(Files.readAllBytes(path))).toString()));}
    private static List<Double> numbers(Object value,int minimum,int maximum,double low,double high)throws IOException {if(!(value instanceof List<?> list)||list.size()<minimum||list.size()>maximum)throw new IOException("Invalid bounded numeric array");var result=new ArrayList<Double>();for(Object item:list){if(!(item instanceof Number n)||!Double.isFinite(n.doubleValue())||n.doubleValue()<low||n.doubleValue()>high)throw new IOException("Invalid finite numeric array member");result.add(n.doubleValue());}return List.copyOf(result);}
    private static List<String> strings(Object value,int minimum,int maximum)throws IOException {if(!(value instanceof List<?> list)||list.size()<minimum||list.size()>maximum)throw new IOException("Invalid bounded string array");var result=new ArrayList<String>();for(Object item:list){if(!(item instanceof String s)||s.length()>1024||s.chars().anyMatch(Character::isISOControl)||result.contains(s))throw new IOException("Invalid or duplicated string array member");result.add(s);}return List.copyOf(result);}
    private static boolean bool(Map<?,?> map,String name)throws IOException {if(!(map.get(name) instanceof Boolean value))throw new IOException("Require explicit boolean: "+name);return value;}
    private static String[] fields(String line,String delimiter){return delimiter.equals("tab")?line.split("\t",-1):line.strip().split("[ \\t]+");}
    private static double finite(String value,String label)throws IOException {try{double result=Double.parseDouble(value);if(!Double.isFinite(result))throw new NumberFormatException();return result;}catch(NumberFormatException failure){throw new IOException("Nonfinite/nonnumeric "+label,failure);}}
    private static long optional(Map<?,?> map,String name,long fallback,long minimum,long maximum)throws IOException {return map.containsKey(name)?whole(map,name,minimum,maximum):fallback;}
    private static Path resolve(Path recipe,String value)throws IOException {token(value,"path",false);Path path=Path.of(value);return (path.isAbsolute()?path:recipe.getParent().resolve(path)).toAbsolutePath().normalize();}
    private static void token(String value,String label,boolean noSpaces)throws IOException {if(value.isEmpty()||value.length()>16384||value.chars().anyMatch(c->Character.isISOControl(c)||noSpaces&&(Character.isWhitespace(c)||Character.isSpaceChar(c))))throw new IOException("Invalid single-line "+label);}
    private static String rbool(boolean value){return value?"TRUE":"FALSE";}
    private static String join(List<?> values){return String.join(",",values.stream().map(String::valueOf).toList());}
}
